9	/// 从网上拉广播星历、生成 UBX-MGA，写到码表 `eph/mga_<utc>.ubx`。
10	class EphService {
11	  /// 创建服务。
12	  EphService({EphBrdc? brdc}) : _brdc = brdc ?? EphBrdc();
13	
14	  static const _tag = 'Eph';
15	
16	  final EphBrdc _brdc;
17	
18	  /// 保证 `eph/` 存在。目录已有则忽略。
19	  Future<void> ensureDir(CompanionClient client) async {
20	    try {
21	      await client.fsMkdir(CompanionFs.ephDir);
22	    } on CompanionFsException catch (e) {
23	      if (e.status != 17) rethrow;
24	    }
25	  }
26	
27	  /// 列出码表上的星历文件（`mga_*.ubx`，兼容旧名 `mga.ubx` / `dump.ubx`）。
28	  Future<List<CompanionFsEntry>> listOnDevice(CompanionClient client) async {
29	    try {
30	      final out = <CompanionFsEntry>[];
31	      var cursor = 0;
32	      while (true) {
33	        final page = await client.fsList(CompanionFs.ephDir, cursor: cursor);
34	        if (page.isEmpty) break;
35	        out.addAll(page.where(_isEphName));
36	        cursor += page.length;
37	        if (page.length < 4) break;
38	      }
39	      out.sort((a, b) {
40	        final ua = MgaUbx.parseFileNameUtc(a.name) ?? a.mtime;
41	        final ub = MgaUbx.parseFileNameUtc(b.name) ?? b.mtime;
42	        return ub.compareTo(ua);
43	      });
44	      return out;
45	    } on CompanionFsException catch (e) {
46	      if (e.status == 2) return [];
47	      rethrow;
48	    }
49	  }
50	
51	  /// 下载 BRDC → 生成 MGA → 上传。码表写完会热加载，不必重启。
52	  Future<EphSyncResult> syncToDevice(
53	    CompanionClient client, {
54	    void Function(EphSyncStage stage)? onStage,
55	    void Function(int done, int total)? onProgress,
56	  }) async {
57	    onStage?.call(EphSyncStage.download);
58	    final bytes = await _brdc.fetchAndBuild();
59	    onStage?.call(EphSyncStage.convert);
60	    final parsed = MgaUbx.parse(bytes);
61	    if (!parsed.ok) {
62	      throw EphException(parsed);
63	    }
64	    onStage?.call(EphSyncStage.upload);
65	    final path = await uploadToDevice(
66	      client,
67	      bytes,
68	      onProgress: onProgress,
69	    );
70	    return EphSyncResult(path: path, bytes: bytes, parsed: parsed);
71	  }
72	
73	  /// 校验后上传。返回设备上的相对路径。
74	  Future<String> uploadToDevice(
75	    CompanionClient client,
76	    Uint8List bytes, {
77	    int? utcSec,
78	    void Function(int done, int total)? onProgress,
79	  }) async {
80	    final parsed = MgaUbx.parse(bytes);
81	    if (!parsed.ok) {
82	      throw EphException(parsed);
83	    }
84	    final name = MgaUbx.fileName(utcSec: utcSec);
85	    final path = CompanionFs.ephPath(name);
86	    await AppLog.i(
87	      _tag,
88	      '上传 $path ${bytes.length} B ${parsed.typeSummary}',
89	    );
90	    await ensureDir(client);
91	    await client.fsUpload(path, bytes, resume: true, onProgress: onProgress);
92	    return path;
93	  }
94	
95	  bool _isEphName(CompanionFsEntry e) {
96	    if (e.isDir) return false;
97	    final n = e.name.toLowerCase();
98	    if (n == 'mga.ubx' || n == 'dump.ubx') return true;
99	    return n.startsWith('mga_') && n.endsWith('.ubx');
100	  }
101	}
102	
103	/// [EphService.syncToDevice] 的阶段。
104	enum EphSyncStage {
105	  /// 拉 IGS BRDC。
106	  download,
107	
108	  /// 编 UBX-MGA。
109	  convert,
110	
111	  /// BLE 写入码表。
112	  upload,
113	}
114	
115	/// 一次同步的结果。
116	class EphSyncResult {
117	  /// 创建结果。
118	  const EphSyncResult({
119	    required this.path,
120	    required this.bytes,
121	    required this.parsed,
122	  });
123	
124	  /// 码表相对路径。
125	  final String path;
126	
127	  /// 生成的 UBX。
128	  final Uint8List bytes;
129	
130	  /// 解析摘要。
131	  final MgaUbxFile parsed;
132	}
133	
134	/// 文件不是码表能注入的 UBX-MGA。
135	class EphException implements Exception {
136	  /// 带上解析结果，方便 UI 展示原因。
137	  EphException(this.file);
138	
139	  /// 解析结果。
140	  final MgaUbxFile file;
141	
142	  @override
143	  String toString() {
144	    if (file.bytes == 0) return '空文件';
145	    if (file.frames == 0) return '不是 UBX（需要 B5 62 开头）';
146	    if (file.checksumFail > 0) return 'UBX 校验失败 ${file.checksumFail} 帧';
147	    if (file.leftover > 0) return '文件尾截断 ${file.leftover} 字节';
148	    if (file.tooBig > 0) return '单帧 payload 超过 ${MgaUbx.maxPayload}';
149	    if (file.mgaFrames == 0) return '没有 UBX-MGA 帧';
150	    if (file.bytes > MgaUbx.maxFileBytes) {
151	      return '文件过大 ${file.bytes} B';
152	    }
153	    return '无效星历文件';
154	  }
155	}
