1	import 'dart:math' as math;
2	import 'dart:typed_data';
3	
4	import 'package:archive/archive.dart';
5	import 'package:sifli_companion/gnss/mga_ubx.dart';
6	
7	/// 把 IGS/BRDC 广播星历（RINEX 3 MIXED NAV）编成 MAX-M10S 用的 UBX-MGA。
8	///
9	/// 不做 AssistNow 账号；公开 BRDC 下载后在手机上生成 MGA-GPS/BDS/GAL/QZSS。
10	abstract class RinexMga {
11	  /// 超过此时差的历元丢掉（秒）。
12	  static const maxAgeSec = 8 * 3600;
13	
14	  /// 解压（若是 gzip）并转换。失败抛 [RinexMgaException]。
15	  static Uint8List convertBytes(Uint8List raw, {DateTime? now}) {
16	    var data = raw;
17	    if (data.length >= 2 && data[0] == 0x1f && data[1] == 0x8b) {
18	      data = Uint8List.fromList(GZipDecoder().decodeBytes(data));
19	    }
20	    return convertText(String.fromCharCodes(data), now: now);
21	  }
22	
23	  /// 解析 RINEX 3 NAV 文本。
24	  static Uint8List convertText(String text, {DateTime? now}) {
25	    final utc = (now ?? DateTime.now()).toUtc();
26	    final recs = _parse(text);
27	    if (recs.isEmpty) {
28	      throw const RinexMgaException('不是 RINEX 3 广播星历（没有 G/C/E/J 历元）');
29	    }
30	
31	    final best = <(String, int), _Rec>{};
32	    for (final r in recs) {
33	      if (r.vals.length < 27) continue;
34	      final key = (r.sys, r.prn);
35	      final prev = best[key];
36	      if (prev == null || r.age(utc) < prev.age(utc)) {
37	        best[key] = r;
38	      }
39	    }
40	
41	    final frames = BytesBuilder(copy: false);
42	    var n = 0;
43	    final keys = best.keys.toList()
44	      ..sort((a, b) {
45	        final c = a.$1.compareTo(b.$1);
46	        return c != 0 ? c : a.$2.compareTo(b.$2);
47	      });
48	    for (final k in keys) {
49	      final r = best[k]!;
50	      if (r.age(utc) > maxAgeSec) continue;
51	      final Uint8List? fr;
52	      switch (r.sys) {
53	        case 'G':
54	          fr = _packGpsLike(0x00, r);
55	        case 'J':
56	          fr = _packGpsLike(0x05, r);
57	        case 'E':
58	          fr = _packGal(r);
59	        case 'C':
60	          fr = r.prn <= 37 ? _packBds(r) : null;
61	        default:
62	          fr = null;
63	      }
64	      if (fr != null) {
65	        frames.add(fr);
66	        n++;
67	      }
68	    }
69	
70	    final out = frames.takeBytes();
71	    if (n == 0 || out.isEmpty) {
72	      throw const RinexMgaException('星历已过期或没有可用卫星');
73	    }
74	    return out;
75	  }
76	}
77	
78	/// 转换失败。
79	class RinexMgaException implements Exception {
80	  /// 人类可读原因。
81	  const RinexMgaException(this.message);
