90	class _Rec {
91	  _Rec(this.sys, this.prn, this.epoch, this.vals);
92	  final String sys;
93	  final int prn;
94	  final DateTime epoch;
95	  final List<double> vals;
96	
97	  double age(DateTime now) => epoch.difference(now).inSeconds.abs().toDouble();
98	}
