100	final _sci = RegExp(r'[+-]?(?:\d+\.\d+|\.\d+|\d+)[Ee][+-]?\d+');
101	final _epoch = RegExp(
102	  r'^([GCEJ])(\d{2})\s+(\d{4})\s+(\d{1,2})\s+(\d{1,2})\s+(\d{1,2})\s+(\d{1,2})\s+(\d{1,2})',
103	);
104	
105	List<double> _floats(String s) {
106	  return _sci
107	      .allMatches(s.replaceAll('D', 'E').replaceAll('d', 'e'))
108	      .map((m) => double.parse(m.group(0)!))
109	      .toList();
110	}
111	
112	List<_Rec> _parse(String text) {
113	  final lines = text.split('\n');
114	  var start = 0;
115	  for (var i = 0; i < lines.length; i++) {
116	    if (lines[i].contains('END OF HEADER')) {
117	      start = i + 1;
118	      break;
119	    }
120	  }
121	
122	  final out = <_Rec>[];
123	  var i = start;
124	  while (i < lines.length) {
125	    final m = _epoch.firstMatch(lines[i]);
126	    if (m == null) {
127	      i++;
128	      continue;
129	    }
130	    final block = <String>[lines[i]];
131	    var j = i + 1;
132	    while (j < lines.length &&
133	        j < i + 8 &&
134	        _epoch.firstMatch(lines[j]) == null) {
135	      block.add(lines[j]);
136	      j++;
137	    }
138	    try {
139	      final epoch = DateTime.utc(
140	        int.parse(m.group(3)!),
141	        int.parse(m.group(4)!),
142	        int.parse(m.group(5)!),
143	        int.parse(m.group(6)!),
144	        int.parse(m.group(7)!),
145	        int.parse(m.group(8)!),
146	      );
147	      final vals = <double>[];
148	      for (var k = 0; k < block.length; k++) {
149	        final ln = block[k];
150	        vals.addAll(_floats(k == 0 ? ln.substring(m.end) : ln));
151	      }
152	      out.add(_Rec(m.group(1)!, int.parse(m.group(2)!), epoch, vals));
153	    } catch (_) {}
154	    i = j;
155	  }
156	  return out;
157	}
