159	int _clamp(int x, int lo, int hi) {
160	  if (x < lo) return lo;
161	  if (x > hi) return hi;
162	  return x;
163	}
164	
165	int _iScale(num? val, double scale, int bits, {required bool signed}) {
166	  final v = val;
167	  var x = 0;
168	  if (v != null && v.isFinite) {
169	    x = (v / scale).round();
170	  }
171	  if (signed) {
172	    final lo = -(1 << (bits - 1));
173	    final hi = (1 << (bits - 1)) - 1;
174	    return _clamp(x, lo, hi);
175	  }
176	  return _clamp(x, 0, bits >= 32 ? 0xffffffff : (1 << bits) - 1);
177	}
