179	int _ura(double? meters) {
180	  const table = [
181	    2.4, 3.4, 4.85, 6.85, 9.65, 13.65, 24.0, 48.0, 96.0, 192.0,
182	    384.0, 768.0, 1536.0, 3072.0, 6144.0,
183	  ];
184	  if (meters == null || meters < 0) return 15;
185	  for (var i = 0; i < table.length; i++) {
186	    if (meters <= table[i]) return i;
187	  }
188	  return 15;
189	}
