191	(int, double) _gpsWeekSow(DateTime dt) {
192	  final epoch = DateTime.utc(1980, 1, 6);
193	  final sec = dt.difference(epoch).inMilliseconds / 1000.0;
194	  final week = sec ~/ 604800;
195	  return (week, sec - week * 604800);
196	}
197	
198	double _sc(num rad) => rad / math.pi;
199	
200	double _v(List<double> v, int i, [double d = 0]) =>
201	    i < v.length ? v[i] : d;
