203	class _Le {
204	  _Le(int n) : b = ByteData(n);
205	  final ByteData b;
206	  Uint8List get bytes => b.buffer.asUint8List();
207	  void u1(int o, int v) => b.setUint8(o, v & 0xff);
208	  void i1(int o, int v) => b.setInt8(o, v);
209	  void u2(int o, int v) => b.setUint16(o, v & 0xffff, Endian.little);
210	  void i2(int o, int v) => b.setInt16(o, v, Endian.little);
211	  void u4(int o, int v) => b.setUint32(o, v & 0xffffffff, Endian.little);
212	  void i4(int o, int v) => b.setInt32(o, v, Endian.little);
213	}
