215	Uint8List _packGpsLike(int mid, _Rec r) {
216	  final v = r.vals;
217	  final af0 = _v(v, 0);
218	  final af1 = _v(v, 1);
219	  final af2 = _v(v, 2);
220	  final iode = _v(v, 3);
221	  final crs = _v(v, 4);
222	  final dn = _v(v, 5);
223	  final m0 = _v(v, 6);
224	  final cuc = _v(v, 7);
225	  final e = _v(v, 8);
226	  final cus = _v(v, 9);
227	  final sqrtA = _v(v, 10);
228	  final toe = _v(v, 11);
229	  final cic = _v(v, 12);
230	  final omega0 = _v(v, 13);
231	  final cis = _v(v, 14);
232	  final i0 = _v(v, 15);
233	  final crc = _v(v, 16);
234	  final omega = _v(v, 17);
235	  final odot = _v(v, 18);
236	  final idot = _v(v, 19);
237	  final acc = _v(v, 23, 2.4);
238	  final health = _v(v, 24).toInt();
239	  final tgd = _v(v, 25);
240	  final iodc = v.length > 26 ? _v(v, 26).toInt() : iode.toInt();
241	  final fit = _v(v, 28);
242	  final toc = _gpsWeekSow(r.epoch).$2;
243	  final p = _Le(68);
244	  p.u1(0, 0x01);
245	  p.u1(2, r.prn);
246	  p.u1(4, (fit == 0 || fit <= 4) ? 0 : 1);
247	  p.u1(5, _ura(acc));
248	  p.u1(6, health & 0x3f);
249	  p.i1(7, _iScale(tgd, math.pow(2, -31).toDouble(), 8, signed: true));
250	  p.u2(8, _clamp(iodc, 0, 65535));
251	  p.u2(10, _iScale(toc, 16, 16, signed: false));
252	  p.i1(13, _iScale(af2, math.pow(2, -55).toDouble(), 8, signed: true));
253	  p.i2(14, _iScale(af1, math.pow(2, -43).toDouble(), 16, signed: true));
254	  p.i4(16, _iScale(af0, math.pow(2, -31).toDouble(), 32, signed: true));
255	  p.i2(20, _iScale(crs, math.pow(2, -5).toDouble(), 16, signed: true));
256	  p.i2(22, _iScale(_sc(dn), math.pow(2, -43).toDouble(), 16, signed: true));
257	  p.i4(24, _iScale(_sc(m0), math.pow(2, -31).toDouble(), 32, signed: true));
258	  p.i2(28, _iScale(cuc, math.pow(2, -29).toDouble(), 16, signed: true));
259	  p.u4(30, _iScale(e, math.pow(2, -33).toDouble(), 32, signed: false));
260	  p.i2(34, _iScale(cus, math.pow(2, -29).toDouble(), 16, signed: true));
261	  p.u4(36, _iScale(sqrtA, math.pow(2, -19).toDouble(), 32, signed: false));
262	  p.u2(40, _iScale(toe, 16, 16, signed: false));
263	  p.i2(42, _iScale(cic, math.pow(2, -29).toDouble(), 16, signed: true));
264	  p.i4(44, _iScale(_sc(omega0), math.pow(2, -31).toDouble(), 32, signed: true));
265	  p.i2(48, _iScale(cis, math.pow(2, -29).toDouble(), 16, signed: true));
266	  p.i4(50, _iScale(_sc(i0), math.pow(2, -31).toDouble(), 32, signed: true));
267	  p.i2(54, _iScale(crc, math.pow(2, -5).toDouble(), 16, signed: true));
268	  p.i4(56, _iScale(_sc(omega), math.pow(2, -31).toDouble(), 32, signed: true));
269	  p.i4(60, _iScale(_sc(odot), math.pow(2, -43).toDouble(), 32, signed: true));
270	  p.i2(64, _iScale(_sc(idot), math.pow(2, -43).toDouble(), 16, signed: true));
271	  return MgaUbx.buildFrame(0x13, mid, p.bytes);
272	}
