274	Uint8List _packGal(_Rec r) {
275	  final v = r.vals;
276	  final toc = _gpsWeekSow(r.epoch).$2;
277	  var bgd = _v(v, 25);
278	  if (v.length > 26) bgd = _v(v, 26);
279	  final p = _Le(76);
280	  p.u1(0, 0x01);
281	  p.u1(2, r.prn);
282	  p.u2(4, _clamp(_v(v, 3).toInt(), 0, 65535));
283	  p.i2(6, _iScale(_sc(_v(v, 5)), math.pow(2, -43).toDouble(), 16, signed: true));
284	  p.i4(8, _iScale(_sc(_v(v, 6)), math.pow(2, -31).toDouble(), 32, signed: true));
285	  p.u4(12, _iScale(_v(v, 8), math.pow(2, -33).toDouble(), 32, signed: false));
286	  p.u4(16, _iScale(_v(v, 10), math.pow(2, -19).toDouble(), 32, signed: false));
287	  p.i4(20, _iScale(_sc(_v(v, 13)), math.pow(2, -31).toDouble(), 32, signed: true));
288	  p.i4(24, _iScale(_sc(_v(v, 15)), math.pow(2, -31).toDouble(), 32, signed: true));
289	  p.i4(28, _iScale(_sc(_v(v, 17)), math.pow(2, -31).toDouble(), 32, signed: true));
290	  p.i4(32, _iScale(_sc(_v(v, 18)), math.pow(2, -43).toDouble(), 32, signed: true));
291	  p.i2(36, _iScale(_sc(_v(v, 19)), math.pow(2, -43).toDouble(), 16, signed: true));
292	  p.i2(38, _iScale(_v(v, 7), math.pow(2, -29).toDouble(), 16, signed: true));
293	  p.i2(40, _iScale(_v(v, 9), math.pow(2, -29).toDouble(), 16, signed: true));
294	  p.i2(42, _iScale(_v(v, 16), math.pow(2, -5).toDouble(), 16, signed: true));
295	  p.i2(44, _iScale(_v(v, 4), math.pow(2, -5).toDouble(), 16, signed: true));
296	  p.i2(46, _iScale(_v(v, 12), math.pow(2, -29).toDouble(), 16, signed: true));
297	  p.i2(48, _iScale(_v(v, 14), math.pow(2, -29).toDouble(), 16, signed: true));
298	  p.u2(50, _iScale(_v(v, 11), 60, 16, signed: false));
299	  p.i4(52, _iScale(_v(v, 0), math.pow(2, -34).toDouble(), 32, signed: true));
300	  p.i4(56, _iScale(_v(v, 1), math.pow(2, -46).toDouble(), 32, signed: true));
301	  p.i1(60, _iScale(_v(v, 2), math.pow(2, -59).toDouble(), 8, signed: true));
302	  p.u1(61, _clamp(_v(v, 23).toInt(), 0, 255));
303	  p.u2(62, _iScale(toc, 60, 16, signed: false));
304	  p.i2(64, _iScale(bgd, math.pow(2, -32).toDouble(), 16, signed: true));
305	  return MgaUbx.buildFrame(0x13, 0x02, p.bytes);
306	}
