308	Uint8List _packBds(_Rec r) {
309	  final v = r.vals;
310	  final sow = _gpsWeekSow(r.epoch).$2;
311	  final toc = (sow - 14.0) % 604800.0;
312	  final p = _Le(88);
313	  p.u1(0, 0x01);
314	  p.u1(2, r.prn);
315	  p.u1(4, _v(v, 24) != 0 ? 1 : 0);
316	  p.u1(5, _clamp(_v(v, 26, _v(v, 3)).toInt(), 0, 255));
317	  p.i2(6, _iScale(_v(v, 2), math.pow(2, -66).toDouble(), 16, signed: true));
318	  p.i4(8, _iScale(_v(v, 1), math.pow(2, -50).toDouble(), 32, signed: true));
319	  p.i4(12, _iScale(_v(v, 0), math.pow(2, -33).toDouble(), 32, signed: true));
320	  p.u4(16, _iScale(toc, 8, 32, signed: false));
321	  p.i2(20, _iScale(_v(v, 25) * 1e9, 0.1, 16, signed: true));
322	  p.u1(22, _ura(_v(v, 23, 2.4)));
323	  p.u1(23, _clamp(_v(v, 3).toInt(), 0, 255));
324	  p.u4(24, _iScale(_v(v, 11), 8, 32, signed: false));
325	  p.u4(28, _iScale(_v(v, 10), math.pow(2, -19).toDouble(), 32, signed: false));
326	  p.u4(32, _iScale(_v(v, 8), math.pow(2, -33).toDouble(), 32, signed: false));
327	  p.i4(36, _iScale(_sc(_v(v, 17)), math.pow(2, -31).toDouble(), 32, signed: true));
328	  p.i2(40, _iScale(_sc(_v(v, 5)), math.pow(2, -43).toDouble(), 16, signed: true));
329	  p.i2(42, _iScale(_sc(_v(v, 19)), math.pow(2, -43).toDouble(), 16, signed: true));
330	  p.i4(44, _iScale(_sc(_v(v, 6)), math.pow(2, -31).toDouble(), 32, signed: true));
331	  p.i4(48, _iScale(_sc(_v(v, 13)), math.pow(2, -31).toDouble(), 32, signed: true));
332	  p.i4(52, _iScale(_sc(_v(v, 18)), math.pow(2, -43).toDouble(), 32, signed: true));
333	  p.i4(56, _iScale(_sc(_v(v, 15)), math.pow(2, -31).toDouble(), 32, signed: true));
334	  p.i4(60, _iScale(_v(v, 7), math.pow(2, -31).toDouble(), 32, signed: true));
335	  p.i4(64, _iScale(_v(v, 9), math.pow(2, -31).toDouble(), 32, signed: true));
336	  p.i4(68, _iScale(_v(v, 16), math.pow(2, -6).toDouble(), 32, signed: true));
337	  p.i4(72, _iScale(_v(v, 4), math.pow(2, -6).toDouble(), 32, signed: true));
338	  p.i4(76, _iScale(_v(v, 12), math.pow(2, -31).toDouble(), 32, signed: true));
339	  p.i4(80, _iScale(_v(v, 14), math.pow(2, -31).toDouble(), 32, signed: true));
340	  return MgaUbx.buildFrame(0x13, 0x03, p.bytes);
341	}
