21	  @override
22	  State<EphPage> createState() => _EphPageState();
23	}
24	
25	enum _EphPhase { idle, syncing, done }
26	
27	class _EphPageState extends State<EphPage> with SingleTickerProviderStateMixin {
28	  final _client = CompanionClient.instance;
29	  final _eph = EphService();
30	
31	  StreamSubscription<CompanionConnState>? _stateSub;
32	  late final AnimationController _sheet;
33	  _EphPhase _phase = _EphPhase.idle;
34	  EphSyncStage? _stage;
35	  String? _error;
36	  List<CompanionFsEntry> _onDevice = [];
37	  bool _listed = false;
38	  int _done = 0;
39	  int _total = 0;
40	  EphSyncResult? _lastResult;
41	
42	  bool get _busy => _phase == _EphPhase.syncing;
43	
44	  bool get _ready => _client.isReady;
45	
46	  CompanionFsEntry? get _latest {
47	    for (final e in _onDevice) {
48	      if (!e.isDir) return e;
49	    }
50	    return null;
51	  }
52	
53	  DateTime? get _lastSync {
54	    DateTime? best;
55	    for (final e in _onDevice) {
56	      if (e.isDir) continue;
57	      final t = _entryTime(e);
58	      if (t != null && (best == null || t.isAfter(best))) best = t;
59	    }
60	    return best;
61	  }
62	
63	  static DateTime? _entryTime(CompanionFsEntry e) {
64	    final utc = MgaUbx.parseFileNameUtc(e.name);
65	    if (utc != null) {
66	      return DateTime.fromMillisecondsSinceEpoch(
67	        utc * 1000,
68	        isUtc: true,
69	      ).toLocal();
70	    }
71	    if (e.mtime > 0) {
72	      return DateTime.fromMillisecondsSinceEpoch(e.mtime * 1000).toLocal();
73	    }
74	    return null;
75	  }
76	
77	  @override
78	  void initState() {
79	    super.initState();
80	    _sheet = AnimationController(
81	      vsync: this,
82	      duration: const Duration(milliseconds: 280),
83	    );
84	    _stateSub = _client.stateStream.listen((_) {
85	      if (mounted) setState(() {});
86	      if (_client.isReady && !_listed && !_busy) {
87	        unawaited(_refreshDevice());
88	      }
89	    });
90	    if (_ready) {
91	      unawaited(_refreshDevice());
92	    }
93	  }
