102	  Future<void> _refreshDevice() async {
103	    if (!_ready || _phase == _EphPhase.syncing) return;
104	    try {
105	      final list = await _eph.listOnDevice(_client);
106	      if (!mounted) return;
107	      setState(() {
108	        _onDevice = list;
109	        _listed = true;
110	      });
111	    } catch (e, st) {
112	      AppTheme.failText('EphList', e, st);
113	      if (!mounted) return;
114	      setState(() => _listed = true);
115	    }
116	  }
117	
118	  Future<void> _sync() async {
119	    final center = TransferCenter.to;
120	    if (_busy) return;
121	    // 页面重建后 _busy 会丢，回中心问一次，避免重复发起把 BLE 通道踩乱。
122	    if (center.isKindRunning(_kind)) return;
123	    if (!_ready) {
124	      setState(() => _error = LocaleKeys.ephNeedBle.tr);
125	      return;
126	    }
127	    if (_client.lastStatus?.isTransferBusy == true) {
128	      setState(() => _error = LocaleKeys.ephMtpBusy.tr);
129	      return;
130	    }
131	
132	    setState(() {
133	      _error = null;
134	      _phase = _EphPhase.syncing;
135	      _stage = EphSyncStage.download;
136	      _done = 0;
137	      _total = 0;
138	    });
139	
140	    // 星历没有取消通道：上传中途只能靠 fsAbort 把整个 BLE 会话打断，
141	    // 代价比等它跑完更大，所以不给取消按钮。
142	    final task = center.begin(
143	      title: LocaleKeys.ephTitle.tr,
144	      kind: _kind,
145	    );
146	
147	    try {
148	      final result = await _eph.syncToDevice(
149	        _client,
150	        onStage: (s) {
151	          center.progress(task, phase: _stageLabel(s));
152	          if (!mounted) return;
153	          setState(() => _stage = s);
154	        },
155	        onProgress: (d, t) {
156	          center.progress(
157	            task,
158	            done: d,
159	            total: t,
160	            transferred: d,
161	            phase: _stageLabel(EphSyncStage.upload),
162	          );
163	          if (!mounted) return;
164	          setState(() {
165	            _done = d;
166	            _total = t;
167	          });
168	        },
169	      );
170	      List<CompanionFsEntry> list = _onDevice;
171	      try {
172	        list = await _eph.listOnDevice(_client);
173	      } catch (_) {}
174	      center.finish(task);
175	      if (!mounted) return;
176	      setState(() {
177	        _onDevice = list;
178	        _listed = true;
179	        _lastResult = result;
180	        _phase = _EphPhase.done;
181	        _stage = null;
182	      });
183	    } catch (e, st) {
184	      center.fail(task, e);
185	      if (!mounted) return;
186	      try {
187	        await _client.fsAbort();
188	      } catch (_) {}
189	      setState(() {
190	        _phase = _EphPhase.idle;
191	        _stage = null;
192	        _error = AppTheme.failText('EphSync', e, st);
193	      });
194	    }
195	  }
