6	/// BLE Companion 协议常量与编解码（服务 `0xFF10`）。
7	///
8	/// 本文件是固件
9	/// `vendor/my_vendor/boards/sf32lb52/my_vendor/include/companion_proto.h`
10	/// 的镜像，**两侧必须同步修改**。协议规格见固件仓库
11	/// `vendor/my_vendor/docs/ble/companion_impl_plan.md`。
12	///
13	/// 拓扑为「一功能一特征」，不做多路复用信道。所有多字节字段一律 **小端**。
14	abstract class CompanionProto {
15	  /// 主服务。
16	  static final service = Guid('FF10');
17	
18	  /// 协议版本，`uint16` 只读。
19	  static final protoVersionChar = Guid('FF11');
20	
21	  /// 设备状态，只读 + Notify，16 字节状态 + 6 字节 Classic 地址（协议 0x0005+）。
22	  static final deviceStatusChar = Guid('FF12');
23	
24	  /// 控制命令，写入 `[opcode:1][param…]`。
25	  static final controlChar = Guid('FF13');
26	
27	  /// 手机 GNSS 下行，写 / 无响应写，24 字节。
28	  static final gnssFixChar = Guid('FF14');
29	
30	  /// 文件系统命令（路径寻址，固件 P1 已实现）。
31	  static final fsCommandChar = Guid('FF15');
32	
33	  /// 文件系统数据（写 + Notify）。文件夹传输走这条 GATT 通道。
34	  static final fsDataChar = Guid('FF16');
35	
36	  /// 通知推送（分片 TLV，App→设备）。
37	  static final notificationChar = Guid('FF17');
38	
39	  /// 轨迹点上行（P2，尚未实现）。
40	  static final trackPointChar = Guid('FF18');
41	
42	  /// 导航轨迹点（分片 lat/lon，App→设备）。
43	  static final navRouteChar = Guid('FF19');
44	
45	  /// 设备信息：运行槽 / 软件 / 硬件 / 2SFBL 版本，只读。旧固件可能没有。
46	  static final deviceInfoChar = Guid('FF1A');
47	
48	  /// App 期望的协议版本。设备返回值不等于此值时应提示升级而非继续通信。
49	  static const expectedVersion = 0x0008;
50	
51	  /// 广播名前缀。**扫描过滤请用 [service] UUID**，名字可被用户改。
52	  static const advNamePrefix = 'Helm One-';
53	
54	  /// 扫描页名称关键字（子串匹配）。含旧名以便未升级的码表仍能扫到。
55	  static const scanKeywords = ['Helm One', 'MyBike'];
56	
57	  /// 广播名是否像本产品码表。
58	  static bool matchesAdvName(String name) {
59	    final n = name.toLowerCase();
60	    return n.contains('helm one') ||
61	        n.contains('helmone') ||
62	        n.contains('mybike') ||
63	        n.contains('vela');
64	  }
65	
66	  /// 期望协商到的 ATT MTU；单包有效载荷为 `mtu - 3`。
67	  static const desiredMtu = 247;
68	}
