70	/// [CompanionStatus.flags] 位域。
71	abstract class CompanionStatusFlag {
72	  /// 设备正在录制（码表已开始一次骑行，含暂停）。
73	  static const recording = 1 << 0;
74	
75	  /// 正在使用手机下行的 GNSS。
76	  static const gpsPhone = 1 << 1;
77	
78	  /// 正在使用内置 GNSS。
79	  static const gpsInternal = 1 << 2;
80	
81	  /// 存储已满。
82	  static const storageFull = 1 << 3;
83	
84	  /// BLE 文件传输进行中。
85	  static const fsBusy = 1 << 4;
86	
87	  /// USB MTP 占用存储，BLE 文件操作会返回 BUSY。
88	  static const usbMtpBusy = 1 << 5;
89	
90	  /// 码表判定正在骑行（未暂停，速度/踏频过阈值）。
91	  static const moving = 1 << 6;
92	
93	  /// 心率传感器已连接。
94	  static const sensorHr = 1 << 8;
95	
96	  /// 踏频 / CSC 传感器已连接。
97	  static const sensorCsc = 1 << 9;
98	
99	  /// 功率计 / CPS 传感器已连接。
100	  static const sensorCps = 1 << 10;
101	}
102	
103	/// 控制特征 `0xFF13` 的操作码。
104	abstract class CompanionCtrl {
105	  /// 保留。
106	  static const nop = 0x00;
107	
108	  /// 开始录制。
109	  static const startRecord = 0x01;
110	
111	  /// 停止录制。
112	  static const stopRecord = 0x02;
113	
114	  /// 请求设备立即回一帧状态 Notify。
115	  static const ping = 0x03;
116	
117	  /// 同步码表 RTC：`[unix_sec:u32le][tz_min:i16le]`（UTC 秒 + 本地相对 UTC 的分钟）。
118	  static const timeSync = 0x04;
119	
120	  /// 中止当前文件传输（P1）。
121	  static const fsAbort = 0x10;
122	
123	  /// 进入同步态，降低其他 Notify 频率（P1）。
124	  static const syncPrep = 0x11;
125	
126	  /// 停止手机下发的导航（不停止录制）。
127	  static const navStop = 0x22;
128	}
