130	/// 通知特征 `0xFF17`：8 字节分片头 + TLV。
131	abstract class CompanionNotif {
132	  static const hdrLen = 8;
133	  static const hdrVer = 0x01;
134	
135	  static const flagFirst = 1 << 0;
136	  static const flagLast = 1 << 1;
137	
138	  static const typeGeneric = 0;
139	  static const typeCall = 1;
140	  static const typeSms = 2;
141	  static const typeApp = 3;
142	  static const typeCalendar = 4;
143	
144	  static const tagAppName = 0x01;
145	  static const tagTitle = 0x02;
146	  static const tagBody = 0x03;
147	  static const tagTimestamp = 0x04;
148	  static const tagPackage = 0x05;
149	  static const tagKey = 0x06;
150	  static const tagIcon = 0x07; // 文件名，不含路径
151	
152	  static const maxTotal = 1024;
153	  static const iconDir = 'notif_icons';
154	  /// 图标文件名最大字符数（不含 NUL），与固件 `COMPANION_NOTIF_ICON_NAME_MAX` 一致。
155	  static const iconNameMax = 80;
156	  static const titleMax = 48;
157	  static const bodyMax = 96;
158	  /// 包名最大字符数（不含 NUL），与固件 `COMPANION_NOTIF_PACKAGE_MAX` 一致。
159	  static const packageMax = 64;
