218	///
219	/// Command 写入：`[cmd:1][tid:1][payload…]`
220	/// Data 帧头 8 字节：`[cmd:1][tid:1][flags:1][status:1][seq:2 le][len:2 le]`
221	abstract class CompanionFs {
222	  static const cmdHdrLen = 2;
223	  static const dataHdrLen = 8;
224	
225	  static const statfs = 0x01;
226	  static const list = 0x02;
227	  static const stat = 0x03;
228	  static const read = 0x04;
229	  static const writeOpen = 0x07;
230	  static const writeData = 0x08;
231	  static const writeClose = 0x09;
232	  static const delete = 0x0A;
233	  static const mkdir = 0x0B;
234	  static const rename = 0x0C;
235	
236	  /// 设备→App：请上传该文件名到设备 `notif_icons/`。
237	  static const need = 0x0D;
238	
239	  static const writeFlagResume = 1 << 0;
240	  static const writeFlagRle = 1 << 1;
241	  static const readFlagRle = 1 << 0;
242	  static const writeOpenReplyLen = 8;
243	
244	  /// NuttX errno → 短文案。
245	  static String errnoText(int status) {
246	    return switch (status) {
247	      2 => '不存在',
248	      5 => '存储写入失败',
249	      13 => '拒绝访问',
250	      16 => '忙',
251	      17 => '已存在',
252	      22 => '参数无效',
253	      28 => '空间不足',
254	      38 => '未实现',
255	      39 => '目录非空',
256	      95 => '不支持',
257	      _ => 'errno=$status',
258	    };
259	  }
260	
261	  static const flagLast = 1 << 0;
262	  static const flagErr = 1 << 1;
263	  static const flagAckReq = 1 << 2;
264	
265	  static const entryFile = 0;
266	  static const entryDir = 1;
267	
268	  /// NuttX `crc32part` 初值 0，多项式 0xedb88320（无最终异或）。
269	  static const crc32Init = 0;
270	
271	  /// 与固件 `crc32part(buf, len, crc)` 一致，用于 WRITE_CLOSE / 续传前缀。
272	  static int crc32Part(List<int> data, [int crc = crc32Init]) {
273	    var value = crc;
274	    for (final b in data) {
275	      value ^= b & 0xff;
276	      for (var i = 0; i < 8; i++) {
277	        if ((value & 1) != 0) {
278	          value = (value >>> 1) ^ 0xedb88320;
279	        } else {
280	          value = value >>> 1;
281	        }
282	      }
283	    }
284	    return value >>> 0;
285	  }
286	
287	  /// WRITE_OPEN 续传回复的 `*.part` 是否就是 [data] 的前缀。
288	  ///
289	  /// 断电后最后几页可能已经计入 size 但内容不是原文。App 若仍从 offset
290	  /// 接着写，CLOSE 会因 CRC 对不上返回 errno 5。
291	  static bool resumePrefixMatches(List<int> data, int offset, int partCrc) {
292	    if (offset <= 0) return true;
293	    if (offset > data.length) return false;
294	    return crc32Part(data.sublist(0, offset)) == (partCrc >>> 0);
295	  }
