387	/// 一帧 `0xFF16` FS Data。
388	class CompanionFsFrame {
389	  /// 解析 8 字节头 + payload。
390	  CompanionFsFrame({
391	    required this.cmd,
392	    required this.tid,
393	    required this.flags,
394	    required this.status,
395	    required this.seq,
396	    required this.payload,
397	  });
398	
399	  final int cmd;
400	  final int tid;
401	  final int flags;
402	  final int status;
403	  final int seq;
404	  final Uint8List payload;
405	
406	  bool get isLast => flags & CompanionFs.flagLast != 0;
407	  bool get isErr => flags & CompanionFs.flagErr != 0;
408	
409	  factory CompanionFsFrame.fromBytes(List<int> data) {
410	    if (data.length < CompanionFs.dataHdrLen) {
411	      throw FormatException('FS 帧短于 8 字节: ${data.length}');
412	    }
413	    final bd = ByteData.sublistView(Uint8List.fromList(data));
414	    final len = bd.getUint16(6, Endian.little);
415	    final end = CompanionFs.dataHdrLen + len;
416	    if (data.length < end) {
417	      throw FormatException('FS 帧 payload 截断: 声明 $len，实际 ${data.length - 8}');
418	    }
419	    return CompanionFsFrame(
420	      cmd: bd.getUint8(0),
421	      tid: bd.getUint8(1),
422	      flags: bd.getUint8(2),
423	      status: bd.getUint8(3),
424	      seq: bd.getUint16(4, Endian.little),
425	      payload: Uint8List.fromList(data.sublist(CompanionFs.dataHdrLen, end)),
426	    );
427	  }
428	}
