430	/// LIST / STAT 条目。
431	class CompanionFsEntry {
432	  const CompanionFsEntry({
433	    required this.type,
434	    required this.size,
435	    required this.mtime,
436	    required this.name,
437	  });
438	
439	  final int type;
440	  final int size;
441	  final int mtime;
442	  final String name;
443	
444	  bool get isDir => type == CompanionFs.entryDir;
445	
446	  static List<CompanionFsEntry> parseList(Uint8List payload) {
447	    final out = <CompanionFsEntry>[];
448	    var i = 0;
449	    final bd = ByteData.sublistView(payload);
450	    while (i + 10 <= payload.length) {
451	      final type = payload[i];
452	      final size = bd.getUint32(i + 1, Endian.little);
453	      final mtime = bd.getUint32(i + 5, Endian.little);
454	      final nlen = payload[i + 9];
455	      i += 10;
456	      if (i + nlen > payload.length) break;
457	      final name = utf8.decode(
458	        payload.sublist(i, i + nlen),
459	        allowMalformed: true,
460	      );
461	      i += nlen;
462	      out.add(CompanionFsEntry(type: type, size: size, mtime: mtime, name: name));
463	    }
464	    return out;
465	  }
466	}
