618	/// 设备信息帧（特征 `0xFF1A`）。V1 为 97 字节；V2 在末尾追加 16 字节 boot 版本。
619	class CompanionDevInfo {
620	  const CompanionDevInfo({
621	    required this.slot,
622	    required this.swVersion,
623	    required this.hwVersion,
624	    this.fwName = '',
625	    this.bootVersion = '',
626	  });
627	
628	  static const swLen = 32;
629	  static const hwLen = 16;
630	  static const nameLen = 48;
631	  static const bootLen = 16;
632	  static const lengthV1 = 1 + swLen + hwLen + nameLen;
633	  static const length = lengthV1 + bootLen;
634	
635	  final int slot;
636	  final String swVersion;
637	  final String hwVersion;
638	  final String fwName;
639	  final String bootVersion;
640	
641	  /// 界面展示用：去掉 `.bin` 后缀，协议里仍是完整文件名。
642	  static String displayFwName(String name) {
643	    const suf = '.bin';
644	    if (name.length > suf.length &&
645	        name.toLowerCase().endsWith(suf)) {
646	      return name.substring(0, name.length - suf.length);
647	    }
648	    return name;
649	  }
650	
651	  String get fwLabel => displayFwName(fwName);
652	
653	  static String _cstr(List<int> data, int off, int len) {
654	    final end = off + len;
655	    var stop = end;
656	    for (var i = off; i < end; i++) {
657	      if (data[i] == 0) {
658	        stop = i;
659	        break;
660	      }
661	    }
662	    return utf8.decode(data.sublist(off, stop), allowMalformed: true).trim();
663	  }
664	
665	  factory CompanionDevInfo.fromBytes(List<int> data) {
666	    if (data.length < lengthV1) {
667	      throw FormatException(
668	        'Companion 设备信息长度至少为 $lengthV1，实际 ${data.length}',
669	      );
670	    }
671	    return CompanionDevInfo(
672	      slot: data[0],
673	      swVersion: _cstr(data, 1, swLen),
674	      hwVersion: _cstr(data, 1 + swLen, hwLen),
675	      fwName: _cstr(data, 1 + swLen + hwLen, nameLen),
676	      bootVersion: data.length >= length
677	          ? _cstr(data, lengthV1, bootLen)
678	          : '',
679	    );
680	  }
