682	  String get slotName => switch (slot) {
683	        CompanionSlot.fw => 'fw',
684	        CompanionSlot.main => 'main',
685	        CompanionSlot.factory => 'factory',
686	        _ => 'unknown',
687	      };
688	
689	  @override
690	  String toString() =>
691	      'CompanionDevInfo(slot=$slotName, sw=$swVersion, hw=$hwVersion'
692	      '${fwName.isEmpty ? '' : ', file=$fwName'}'
693	      '${bootVersion.isEmpty ? '' : ', boot=$bootVersion'})';
694	}
