9	class CompanionGnssFix {
10	  /// 按协议字段构造。各字段均为已换算到协议单位的整数。
11	  const CompanionGnssFix({
12	    required this.latE7,
13	    required this.lonE7,
14	    required this.altMm,
15	    required this.speedCentiKmh,
16	    required this.courseDeg,
17	    required this.utcSec,
18	    required this.fixQuality,
19	    required this.satellites,
20	    required this.hdopX10,
21	  });
22	
23	  /// 帧字节长度。
24	  static const length = 24;
25	
26	  /// 纬度 × 1e7，WGS84。
27	  final int latE7;
28	
29	  /// 经度 × 1e7。
30	  final int lonE7;
31	
32	  /// 海拔，毫米。
33	  final int altMm;
34	
35	  /// 速度，0.01 km/h。
36	  final int speedCentiKmh;
37	
38	  /// 航向，0–359 度。
39	  final int courseDeg;
40	
41	  /// UTC Unix 时间戳，秒。
42	  final int utcSec;
43	
44	  /// 定位质量，取值见 [CompanionFixQuality]。
45	  final int fixQuality;
46	
47	  /// 参与定位的卫星数。
48	  final int satellites;
49	
50	  /// 水平精度因子 × 10。
51	  final int hdopX10;
52	
53	  /// 由 geolocator 的 [Position] 换算构造。
54	  ///
55	  /// geolocator 不提供卫星数与 HDOP，因此 [satellites] 记 0，并用
56	  /// [Position.accuracy]（米）近似 [hdopX10]。[fixQuality] 依据是否有海拔数据
57	  /// 区分 2D / 3D。
58	  factory CompanionGnssFix.fromPosition(Position p) {
59	    final hasAltitude = p.altitude != 0 || p.altitudeAccuracy > 0;
60	
61	    return CompanionGnssFix(
62	      latE7: _clampInt32((p.latitude * 1e7).round()),
63	      lonE7: _clampInt32((p.longitude * 1e7).round()),
64	      altMm: _clampInt32((p.altitude * 1000).round()),
65	
66	      // Position.speed 是 m/s，协议要 0.01 km/h：m/s * 3.6 * 100 = m/s * 360。
67	      speedCentiKmh: _clampUint16((p.speed * 360).round()),
68	      courseDeg: _clampUint16(p.heading.isFinite ? p.heading.round() % 360 : 0),
69	      utcSec: p.timestamp.millisecondsSinceEpoch ~/ 1000,
70	      fixQuality:
71	          hasAltitude ? CompanionFixQuality.fix3d : CompanionFixQuality.fix2d,
72	      satellites: 0,
73	      hdopX10: _clampUint8((p.accuracy * 10).round()),
74	    );
75	  }
