93	  /// 解析 24 字节帧。轨迹点特征 `0xFF18` 与本结构同布局，末字节含义不同。
94	  factory CompanionGnssFix.fromBytes(List<int> data) {
95	    if (data.length < length) {
96	      throw FormatException('GNSS 帧长度应为 $length，实际 ${data.length}');
97	    }
98	
99	    final bd = ByteData.sublistView(Uint8List.fromList(data));
100	    return CompanionGnssFix(
101	      latE7: bd.getInt32(0, Endian.little),
102	      lonE7: bd.getInt32(4, Endian.little),
103	      altMm: bd.getInt32(8, Endian.little),
104	      speedCentiKmh: bd.getUint16(12, Endian.little),
105	      courseDeg: bd.getUint16(14, Endian.little),
106	      utcSec: bd.getUint32(16, Endian.little),
107	      fixQuality: bd.getUint8(20),
108	      satellites: bd.getUint8(21),
109	      hdopX10: bd.getUint8(22),
110	    );
111	  }
